function generatePassword(): string {
  // URL-safe, no ambiguous chars, 16 chars
  return randomBytes(24).toString("base64url").replace(/[-_]/g, "x").slice(0, 16);
}

/**
 * Guest memory / ballooning — see lib/vm-memory-policy.ts for the full story.
 *
 * History: until 2026-09-14 VMs had no balloon floor (`memory:` was a hard
 * reservation and the primary OOM-crashed). From 2026-09-14 every VM got a
 * 50% floor (min 1024), which let pvestatd squeeze a paying customer's 4 GB
 * Valheim VM to ~1.8 GB on a busy node-4 (2026-10-01). Now customer VMs get a
 * floor EQUAL to their RAM (NXEON_BALLOON_POLICY=pin, default; `off` =
 * balloon 0; `floor` = the old 50% as an emergency escape hatch), and the
 * host-side protection the floor used to give moved to the scheduler's live
 * RAM guard (lib/node-ram-guard.ts), which refuses to place pinned RAM a
 * node cannot physically back.
 */
function balloonForVm(memoryMB: number): number {
  return balloonFor(memoryMB, balloonPolicy());
}

async function loadServer(job: Job): Promise<Server & { plan: any; gamePlan: any; osTemplate: any; node: any; user: any }> {
  const server = await db.server.findUnique({
    where: { id: job.serverId! },
    // `user` (email) + `node` (publicIp) are needed for the deployment
    // confirmation email fired on provision success; the rest is used throughout.
    // `gamePlan` — a game order's REAL entitlement (its own ramMB/cpuCores/
    // diskGB, the exact numbers advertised and sold), not `plan` (the linked
    // basePlan, which only exists because the host only offers 4 discrete VPS
    // tiers and a game plan's advertised size gets rounded UP to the nearest
      await db.server.updateMany({ where: { ipAddress: dedicated.address }, data: { ipAddress: null, ipv6: null } });
      await releaseDedicatedIp(server.id).catch(() => {});
      dedicated = null;
      ip = server.ipAddress ?? (await allocateIp(server.nodeId, server.id, { heldElsewhere: nodeHeld }));
      sshPort = server.sshPort ?? (await allocateSshPort(server.nodeId, server.id));
      await db.server.update({
        where: { id: server.id },
        data: { vmid, ipAddress: ip, sshPort, rootPassword: null, rootPasswordEnc: encryptSecret(password) },
      });
    } else {
      throw e;
    }
  }

  const stockBaseVmid = server.osTemplate.baseVmid ?? server.osTemplate.vmid;
  // Golden game template (lib/golden-template.ts): opt-in via
  // NXEON_GOLDEN_GAME_TEMPLATE, and only if THIS node really has it as a
  // tagged template no bigger than the order's disk — otherwise the stock
  // base, exactly as before. Decided once per attempt; on a retry where the VM
  // already exists the clone is skipped anyway, and `golden` below only
  // changes the cloud-init package block (golden clones already carry it).
  const goldenVmid = goldenTemplateVmidFromEnv(process.env.NXEON_GOLDEN_GAME_TEMPLATE, server.osTemplate?.family ?? null);
  let goldenConfig: any = null;
  if (goldenVmid && isGame && stockBaseVmid === GOLDEN_SOURCE_VMID) {
    goldenConfig = await conn.get(`/nodes/${conn.node}/qemu/${goldenVmid}/config`).catch(() => null);
  }
  const cloneSource = chooseCloneSource({
    baseVmid: stockBaseVmid,
    isGame,
    goldenVmid,
    nodeConfig: goldenConfig,
    targetDiskGB: effectiveDiskGB(server.gamePlan?.diskGB ?? server.plan.diskGB, server.extraDiskGB),
  });
  const baseVmid = cloneSource.vmid;
  if (goldenVmid) console.log(`[worker] provision ${server.hostname}: clone source ${baseVmid} (${cloneSource.reason})`);
  // PROVISION must be re-runnable. `vmid` is persisted BEFORE the clone, so a retry
  // (worker restart mid-clone, or any transient failure in the steps below) would
  // re-issue a clone onto an id that now exists — Proxmox rejects it and all 3
  // attempts fail identically, stranding a half-built VM in ERROR. Everything after
  // the clone is idempotent, so skip it when the VM is already present.
  let vmAlreadyExists = false;
  try {
    await conn.vmStatus(vmid);
    vmAlreadyExists = true;
  } catch {
    vmAlreadyExists = false;
  }
  if (vmAlreadyExists) {
    console.log(`[worker] vm ${vmid} already exists — skipping clone (idempotent retry)`);
  } else {
    await step("Allocating your server…");
    // Linked clone (ZFS clone of the template's base snapshot, ~2s) only for a
    // golden template, only when explicitly enabled, and only onto the
    // template's own storage — see linkedCloneAllowed. Everything else stays a
    // full copy exactly as before. Measured on node-2 2026-10-01: full clone of
    // the 4.2 GB golden template 67.7s, linked 2.1s (stock 9000 full: 24.5s).
    const linked = cloneSource.golden && linkedCloneAllowed({
      enabled: process.env.NXEON_GOLDEN_LINKED_CLONE === "1",
      templateDiskSpec: goldenConfig?.scsi0 ?? null,
      targetStorage: storage,
    });
    const cloneUpid = await conn.post(
      `/nodes/${conn.node}/qemu/${baseVmid}/clone`,
      linked ? { newid: vmid, name: server.hostname, full: 0 } : { newid: vmid, name: server.hostname, full: 1, storage },
    );
    await conn.waitForTask(cloneUpid, 600_000);
  }

  // Per-server cloud-init snippet (base + panel/app install + add-ons).
  //
  // This write used to be `.catch`'d to a console line (M7 #10). It must not be:
  // the very next config POST sets `cicustom: vendor=…/nxeon-<vmid>.yaml`, so a
  // failed write hands the VM a vendor-data file that does not exist. Root SSH
  // config, the guest agent, the setup script, START-WITH-CLAUDE.md and the MOTD
  // all silently vanish, and the customer is still told the server is ready.
  // Failing here is recoverable — the job retries, and the clone above is
  // idempotent. Continuing is not.
  // NxCloud hook: if this VM is the backing box for a managed Nextcloud instance,
  // generate its one-time admin password (persisted, once) and get the idempotent
  // install script to bake into cloud-init. Null for an ordinary VPS.
  // Per-server admin/RCON passwords for families whose catalog script ships a
  // shared placeholder (`changeme12`) — see adminSecretFieldsToMint. Minted
  // ONCE and persisted into gameConfig BEFORE the snippet is built, so the
  // customer can read it in Settings, applyGameConfigEnv substitutes it like
  // any checkout value, and a PROVISION retry / GAME_REINSTALL reuses it.
  if (isGame) {
  // (confirmed 72 of 120 game plans in the catalog had this exact gap, not a
  // one-off). Plain VPS orders (no gamePlan) are correctly sized from `plan`
  // either way, so this is additive, not a behavior change for them.
  const effectiveCores = server.gamePlan?.cpuCores ?? server.plan.cpuCores;
  const effectiveRamMB = server.gamePlan?.ramMB ?? server.plan.ramMB;
  // DISK — 2026-09-08 policy: the advertised number IS the delivered number,
  // full stop, matching RAM/cores above. No linked-basePlan floor.
  //
  // This intentionally drops the interim `Math.max(gamePlan, basePlan)` floor
  // from 2026-09-06. That floor existed only because sizing disk straight from
  // `gamePlan` once broke Project Zomboid — its entry plan ("6 GB / 8 players")
  // advertised 15GB, the real install needs more, and it died at 91.8% with
  // `No space left on device`. But the floor's actual behavior was "inherit
  // whatever the linked VPS tier defaults to" (72-85GB overage on to over 100
  // of 121 plans — e.g. an advertised-40GB ARK order silently got 80GB) — a
  // margin leak with no relationship to what any given game actually needs.
  // Removing it means the catalog's own advertised diskGB is now the ONLY
  // thing standing between an order and a failed install, so before this
  // shipped every plan with hard evidence of being unsafe at its advertised
  // size was corrected to what the game actually needs (see the same-day
  // catalog commit and docs/DOCUMENTATION.md's "advertised disk audit" entry):
  // Project Zomboid's entry tier and Team Fortress 2's entry tier, both
  // confirmed by a real provision on node-2, not inferred.
  //
  // The remaining ~119 plans have NOT each been individually load-tested
  // against their advertised size — only fixed where the ongoing catalog
  // sweep has already produced hard evidence. A plan whose real install turns
  // out to exceed its advertised diskGB will now fail provisioning instead of
  // silently over-delivering; treat that as a signal to fix the CATALOG entry
  // (the honest fix), not to re-add a blanket floor here (the thing that hid
  // this exact problem in the first place).
  const effectiveBaseDiskGB = server.gamePlan?.diskGB ?? server.plan.diskGB;
  const cfg: Record<string, any> = {
    cores: effectiveCores,
    memory: effectiveRamMB,
    balloon: balloonForVm(effectiveRamMB),
    ciuser: "root",
    cipassword: password,
    sshkeys,
    nameserver: "1.1.1.1 8.8.8.8",
    onboot: 1,
    // Omit cicustom (rather than deleting it) when there's no fresh per-VM
    // snippet to point it at — see the long comment above ("Configuring the
    // network…") for why the template's own inherited value must survive
    // here, not be cleared. It only works correctly because every onboarded
    // node's templates have a valid, node-scoped storage reference for it
    // (fixed 2026-09-05 after the templates migrated from primary carried the
    // wrong storage name).
    ...(cicustom ? { cicustom } : {}),
    tags: `${process.env.NXEON_TAG ?? "nxeon"};user-${server.userId.slice(0, 8)}`,
  };
  if (dedicated && dedicated.virtualMac) {
    // Public bridge + a real bound Virtual MAC. OVH: from its Virtual MAC
    // API. Hetzner: from Robot's `/ip/{ip}/mac` (corrected 2026-09-29 —
    // allocateDedicatedIp() used to hardcode "" for Hetzner on the mistaken
    // belief it had no such mechanism; it does, and Hetzner's own
    // network-abuse filtering actively polices this — see lib/hetzner.ts's
    // header comment for the real incident). Either way: failover/additional
    // IP as /32 with the provider's gateway for it.
    cfg.net0 = `virtio=${dedicated.virtualMac},bridge=vmbr0`;
    cfg.ipconfig0 = `ip=${dedicated.address}/32,gw=${dedicated.gateway}`;
  } else if (dedicated) {
    // Best-effort fallback ONLY — reached when Hetzner's MAC lookup/create
    // itself failed (allocateDedicatedIp logs loudly and returns "" rather
    // than blocking a paying customer's order over it). Still forces the
    // public bridge explicitly rather than trusting the clone's inherited
    // bridge: node-2's (and any onboard-node.sh node's) templates default to
    // the isolated, NAT-only vmbr1, which has no path to a real public IP at
    // all — confirmed live 2026-09-29, the first real bug found here, fixed
    // separately from the MAC issue above. Proxmox auto-assigns a MAC when
    // none is given; it will NOT be Hetzner-registered, so this guest may
    // still trip Hetzner's abuse filter until the MAC lookup/create above
    // succeeds on a later attempt.
    cfg.net0 = `virtio,bridge=vmbr0`;
    cfg.ipconfig0 = `ip=${dedicated.address}/32,gw=${dedicated.gateway}`;
  } else {
    // Node-aware gateway: a second node with a different subnet must not get the primary's gateway.
    cfg.ipconfig0 = `ip=${ip}/24,gw=${gatewayIp(nodeRow?.subnetPrefix)}`;
  }
  await conn.post(`/nodes/${conn.node}/qemu/${vmid}/config`, cfg);

  // Provision at the EFFECTIVE size: the plan's allowance plus any extra disk the
  // customer bought as a deploy-time upsell, so the VM is born the right size and
  // no separate DISK_EXPAND job is needed on a fresh order.
  await conn.put(`/nodes/${conn.node}/qemu/${vmid}/resize`, {
    disk: "scsi0",
    size: `${effectiveDiskGB(effectiveBaseDiskGB, server.extraDiskGB)}G`,
  });

  // Port forwarding is what makes the `ssh root@host -p <port>` line below true
  // for a NAT server. If it cannot be proved, the readiness message says so
  // instead of printing a command that will hang (H5 + M7 #10). Not fatal: the
  // VM itself is fine and a failed PROVISION would flip it to ERROR and release
  // its IP, which is a worse outcome than a missing forward.
  let natError: Error | null = null;
  if (!SANDBOX && !dedicated) natError = await syncPortForwardsBestEffort(`provision ${server.hostname}`);

  // Idempotent start. A worker restart (e.g. a deploy) can interrupt a provision
  // AFTER the VM was already created and started; the reaper then re-queues the job.
  // Starting an already-running VM makes Proxmox's start task fail with "already
  // running", which — before this guard — stranded a perfectly good, reachable VM in
